    "code": "// L5-06 — Đối chiếu infix, postfix, prefix\n#include <bits/stdc++.h>\nusing namespace std;\n\nint priority(char c) {\n    if (c == '^')\n        return 3;\n    if (c == '*' || c == '/')\n        return 2;\n    if (c == '+' || c == '-')\n        return 1;\n    return 0;\n}\nstring postfix(string s) {\n    string out;\n    stack<char> ops;\n    for (char c : s) {\n        if (isspace((unsigned char)c))\n            continue;\n        if (isalnum((unsigned char)c))\n            out += c;\n        else if (c == '(')\n            ops.push(c);\n        else if (c == ')') {\n            while (!ops.empty() && ops.top() != '(') {\n                out += ops.top();\n                ops.pop();\n            }\n            if (ops.empty())\n                throw runtime_error(\"Ngoac sai\");\n            ops.pop();\n        } else if (priority(c)) {\n            while (!ops.empty() && ops.top() != '(' &&\n                   (priority(ops.top()) > priority(c) ||\n                    (priority(ops.top()) == priority(c) && c != '^'))) {\n                out += ops.top();\n                ops.pop();\n            }\n            ops.push(c);\n        } else\n            throw runtime_error(\"Ky tu sai\");\n    }\n    while (!ops.empty()) {\n        if (ops.top() == '(')\n            throw runtime_error(\"Ngoac sai\");\n        out += ops.top();\n        ops.pop();\n    }\n    return out;\n}\nint main() {\n    for (string s : {\"A+B\", \"A*B+C\", \"A*(B+C)\", \"A-(B-(C-D))\", \"A-B-C-D\"}) {\n        string post = postfix(s);\n        stack<string> st;\n        for (char c : post) {\n            if (isalnum((unsigned char)c))\n                st.push(string(1, c));\n            else {\n                string b = st.top();\n                st.pop();\n                string a = st.top();\n                st.pop();\n                st.push(string(1, c) + a + b);\n            }\n        }\n        cout << s << \" | \" << post << \" | \" << st.top() << \"\\n\";\n    }\n}\n",
