    "code": "// L5-11 — Queue mảng vòng\n#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Queue {\n    static const int CAP = 3;\n    int a[CAP] = {}, head = 0, size = 0;\n    bool empty() {\n        return size == 0;\n    }\n    bool full() {\n        return size == CAP;\n    }\n    bool enqueue(int x) {\n        if (full())\n            return false;\n        a[(head + size) % CAP] = x;\n        ++size;\n        return true;\n    }\n    bool dequeue(int &x) {\n        if (empty())\n            return false;\n        x = a[head];\n        head = (head + 1) % CAP;\n        --size;\n        return true;\n    }\n    int front() {\n        if (empty())\n            throw runtime_error(\"EMPTY\");\n        return a[head];\n    }\n};\nint main() {\n    Queue q;\n    for (int x : {5, 3, 2, 4})\n        cout << (q.enqueue(x) ? \"ENQUEUE\" : \"FULL\") << \"\\n\";\n    int x;\n    q.dequeue(x);\n    q.enqueue(4);\n    cout << \"front=\" << q.front() << \"\\n\";\n    while (q.dequeue(x))\n        cout << x << \" \";\n    cout << \"EMPTY\\n\";\n}\n",
