    "code": "// L5-12 — Queue bằng DSLK\n#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Node {\n    int value;\n    Node *next;\n};\nstruct List {\n    Node *head = nullptr, *tail = nullptr;\n    Node *find(int x) {\n        for (Node *p = head; p; p = p->next)\n            if (p->value == x)\n                return p;\n        return nullptr;\n    }\n    void front(int x) {\n        head = new Node{x, head};\n        if (!tail)\n            tail = head;\n    }\n    void back(int x) {\n        Node *p = new Node{x, nullptr};\n        if (tail)\n            tail->next = p;\n        else\n            head = p;\n        tail = p;\n    }\n    void after(Node *q, int x) {\n        if (!q)\n            return;\n        Node *p = new Node{x, q->next};\n        q->next = p;\n        if (tail == q)\n            tail = p;\n    }\n    Node *pickHead() {\n        if (!head)\n            return nullptr;\n        Node *p = head;\n        head = p->next;\n        p->next = nullptr;\n        if (!head)\n            tail = nullptr;\n        return p;\n    }\n    void eraseAfter(Node *q) {\n        if (!q || !q->next)\n            return;\n        Node *p = q->next;\n        q->next = p->next;\n        if (tail == p)\n            tail = q;\n        delete p;\n    }\n    void erase(int x) {\n        if (!head)\n            return;\n        if (head->value == x) {\n            delete pickHead();\n            return;\n        }\n        Node *q = head;\n        while (q->next && q->next->value != x)\n            q = q->next;\n        eraseAfter(q);\n    }\n    void clear() {\n        while (head)\n            delete pickHead();\n    }\n    int count() {\n        int n = 0;\n        for (Node *p = head; p; p = p->next)\n            n++;\n        return n;\n    }\n    long long sum() {\n        long long s = 0;\n        for (Node *p = head; p; p = p->next)\n            s += p->value;\n        return s;\n    }\n    Node *nth(int n) {\n        Node *p = head;\n        for (int i = 1; p && i < n; i++)\n            p = p->next;\n        return n > 0 ? p : nullptr;\n    }\n    void sortedInsert(int x) {\n        if (!head || x <= head->value) {\n            front(x);\n            return;\n        }\n        Node *q = head;\n        while (q->next && q->next->value < x)\n            q = q->next;\n        after(q, x);\n    }\n    void print() {\n        for (Node *p = head; p; p = p->next)\n            cout << p->value << \" \";\n        cout << \"\\n\";\n    }\n    ~List() {\n        clear();\n    }\n};\nint main() {\n    List q;\n    for (int x : {5, 3, 2})\n        q.back(x);\n    while (q.head) {\n        cout << \"front=\" << q.head->value << \"\\n\";\n        delete q.pickHead();\n    }\n    cout << \"EMPTY\\n\";\n}\n",
