    "code": "// L6-01 — Nhận dạng cây và các khái niệm\n#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n};\nNode *insert(Node *p, int x) {\n    if (!p)\n        return new Node{x};\n    if (x < p->key)\n        p->left = insert(p->left, x);\n    else if (x > p->key)\n        p->right = insert(p->right, x);\n    return p;\n}\nNode *find(Node *p, int x) {\n    if (!p || p->key == x)\n        return p;\n    return find(x < p->key ? p->left : p->right, x);\n}\nvoid inorder(Node *p) {\n    if (!p)\n        return;\n    inorder(p->left);\n    cout << p->key << \" \";\n    inorder(p->right);\n}\nvoid structure(Node *p, int depth = 0) {\n    if (!p)\n        return;\n    structure(p->right, depth + 1);\n    cout << string(depth * 2, ' ') << p->key << \"\\n\";\n    structure(p->left, depth + 1);\n}\nint count(Node *p) {\n    return p ? 1 + count(p->left) + count(p->right) : 0;\n}\nint leaves(Node *p) {\n    return !p ? 0 : !p->left && !p->right ? 1 : leaves(p->left) + leaves(p->right);\n}\nint height(Node *p) {\n    return p ? 1 + max(height(p->left), height(p->right)) : -1;\n}\nNode *erase(Node *p, int x) {\n    if (!p)\n        return p;\n    if (x < p->key)\n        p->left = erase(p->left, x);\n    else if (x > p->key)\n        p->right = erase(p->right, x);\n    else {\n        if (!p->left) {\n            Node *q = p->right;\n            delete p;\n            return q;\n        }\n        if (!p->right) {\n            Node *q = p->left;\n            delete p;\n            return q;\n        }\n        Node *q = p->right;\n        while (q->left)\n            q = q->left;\n        p->key = q->key;\n        p->right = erase(p->right, q->key);\n    }\n    return p;\n}\nvoid clear(Node *p) {\n    if (!p)\n        return;\n    clear(p->left);\n    clear(p->right);\n    delete p;\n}\nint main() {\n    Node *r = nullptr;\n    for (int x : {4, 2, 6, 1, 3})\n        r = insert(r, x);\n    structure(r);\n    cout << \"root=\" << r->key << \" nodes=\" << count(r) << \" leaves=\" << leaves(r)\n         << \" height=\" << height(r) << \"\\n\";\n    clear(r);\n}\n",
