    "code": "// L7-10 — Quick Sort - pivot ở giữa\n#include <bits/stdc++.h>\nusing namespace std;\n\nvoid print(const vector<int> &a) {\n    for (int x : a)\n        cout << x << \" \";\n    cout << \"\\n\";\n}\nvoid quick(vector<int> &a, int l, int r) {\n    if (l >= r)\n        return;\n    int i = l, j = r, pivot = a[l + (r - l) / 2];\n    while (i <= j) {\n        while (a[i] < pivot)\n            i++;\n        while (a[j] > pivot)\n            j--;\n        if (i <= j) {\n            swap(a[i], a[j]);\n            i++;\n            j--;\n        }\n    }\n    print(a);\n    if (l < j)\n        quick(a, l, j);\n    if (i < r)\n        quick(a, i, r);\n}\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int &x : a)\n        cin >> x;\n    quick(a, 0, n - 1);\n    print(a);\n}\n",
