    "code": "// L8-05 — Merge Sort dùng chỉ số\n#include <bits/stdc++.h>\nusing namespace std;\n\nvoid print(const vector<int> &a) {\n    for (int x : a)\n        cout << x << \" \";\n    cout << \"\\n\";\n}\nvoid mergesort(vector<int> &a, int l, int r) {\n    if (l >= r)\n        return;\n    int m = l + (r - l) / 2;\n    mergesort(a, l, m);\n    mergesort(a, m + 1, r);\n    vector<int> tmp;\n    int i = l, j = m + 1;\n    while (i <= m && j <= r) {\n        if (a[i] <= a[j])\n            tmp.push_back(a[i++]);\n        else\n            tmp.push_back(a[j++]);\n    }\n    while (i <= m)\n        tmp.push_back(a[i++]);\n    while (j <= r)\n        tmp.push_back(a[j++]);\n    for (int k = 0; k < (int)tmp.size(); k++)\n        a[l + k] = tmp[k];\n    print(a);\n}\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int &x : a)\n        cin >> x;\n    mergesort(a, 0, n - 1);\n    print(a);\n}\n",
