    "code": "// L8-04 — Merge Sort dùng hai danh sách con\n#include <bits/stdc++.h>\nusing namespace std;\n\nvoid print(const vector<int> &a) {\n    for (int x : a)\n        cout << x << \" \";\n    cout << \"\\n\";\n}\nvoid mergesort(vector<int> &a) {\n    if (a.size() < 2)\n        return;\n    int m = a.size() / 2;\n    vector<int> L(a.begin(), a.begin() + m), R(a.begin() + m, a.end());\n    mergesort(L);\n    mergesort(R);\n    int i = 0, j = 0, k = 0;\n    while (i < (int)L.size() && j < (int)R.size())\n        a[k++] = L[i] <= R[j] ? L[i++] : R[j++];\n    while (i < (int)L.size())\n        a[k++] = L[i++];\n    while (j < (int)R.size())\n        a[k++] = R[j++];\n    print(a);\n}\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int &x : a)\n        cin >> x;\n    mergesort(a);\n    print(a);\n}\n",
